action.code:
if (N % 2 != 0) {
    throw std::invalid_argument("Number of intervals N must be even for Simpson's rule");
}

double h = (m_b - m_a) / N;
double sum = m_f->eval(m_a) + m_f->eval(m_b);

for (int i = 1; i < N; i += 2) {
    double x = m_a + i * h;
    sum += 4 * m_f->eval(x);
}

for (int i = 2; i < N - 1; i += 2) {
    double x = m_a + i * h;
    sum += 2 * m_f->eval(x);
}

return (h / 3) * sum * m_sign;

